(function(){var btn=document.getElementById("fsToggle");if(!btn)return;function isFullscreen(){return!!(document.fullscreenElement||document.webkitFullscreenElement||document.mozFullScreenElement||document.msFullscreenElement)}function updateIcon(){if(isFullscreen()){btn.classList.add("expanded");btn.title="Exit fullscreen"}else{btn.classList.remove("expanded");btn.title="Enter fullscreen"}}btn.addEventListener("click",function(e){e.stopPropagation();e.preventDefault();try{if(isFullscreen()){if(document.exitFullscreen)document.exitFullscreen();else if(document.webkitExitFullscreen)document.webkitExitFullscreen();else if(document.mozCancelFullScreen)document.mozCancelFullScreen();else if(document.msExitFullscreen)document.msExitFullscreen()}else{var el=document.documentElement;if(el.requestFullscreen)el.requestFullscreen();else if(el.webkitRequestFullscreen)el.webkitRequestFullscreen();else if(el.mozRequestFullScreen)el.mozRequestFullScreen();else if(el.msRequestFullscreen)el.msRequestFullscreen()}}catch(err){}});document.addEventListener("fullscreenchange",updateIcon);document.addEventListener("webkitfullscreenchange",updateIcon);document.addEventListener("mozfullscreenchange",updateIcon);document.addEventListener("MSFullscreenChange",updateIcon)})();